function creerFilePriorite() {
  const heap = [];

  function getParentIndex(i) { return Math.floor((i - 1) / 2); }
  function getLeftChildIndex(i) { return 2 * i + 1; }
  function getRightChildIndex(i) { return 2 * i + 2; }

  function swap(i, j) {
    [heap[i], heap[j]] = [heap[j], heap[i]];
  }

  return {
    enqueue(val, priorite) {
      heap.push({ val, priorite });
      let index = heap.length - 1;
      while (index > 0) {
        let parentIndex = getParentIndex(index);
        if (heap[index].priorite < heap[parentIndex].priorite) {
          swap(index, parentIndex);
          index = parentIndex;
        } else {
          break;
        }
      }
    },
    dequeue() {
      if (heap.length === 0) return null;
      if (heap.length === 1) return heap.pop().val;

      const min = heap[0].val;
      heap[0] = heap.pop();

      let index = 0;
      while (true) {
        let left = getLeftChildIndex(index);
        let right = getRightChildIndex(index);
        let smallest = index;

        if (left < heap.length && heap[left].priorite < heap[smallest].priorite) {
          smallest = left;
        }
        if (right < heap.length && heap[right].priorite < heap[smallest].priorite) {
          smallest = right;
        }

        if (smallest !== index) {
          swap(index, smallest);
          index = smallest;
        } else {
          break;
        }
      }
      return min;
    },
    taille() {
      return heap.length;
    }
  };
}
