function creerEventEmitter() {
  const events = {};

  return {
    on(event, fn) {
      if (!events[event]) {
        events[event] = [];
      }
      events[event].push(fn);
    },
    off(event, fn) {
      if (!events[event]) return;
      events[event] = events[event].filter(listener => listener !== fn);
    },
    emit(event, ...args) {
      if (!events[event]) return;
      events[event].forEach(fn => fn(...args));
    }
  };
}
