    while (i < a.length) merged.push(a[i++]);
    while (j < b.length) merged.push(b[j++]);

    const mid = Math.floor(merged.length / 2);
    if (merged.length % 2 === 0) {
        return (merged[mid - 1] + merged[mid]) / 2;
    } else {
        return merged[mid];
    }
}

function plusLongueSousSuiteCroissante(tab) {
    if (tab.length === 0) return 0;
    const tails = [];
    for (let x of tab) {
        let i = 0, j = tails.length;
        while (i !== j) {
            let m = Math.floor((i + j) / 2);
            if (tails[m] < x) i = m + 1;
            else j = m;
        }
        tails[i] = x;
        if (i === tails.length) tails.push(x); // This line is logically handled by tails[i]=x if i < length
    }
    // Correcting the binary search logic for tails array
    const dp = [];
    for (let x of tab) {
        let low = 0, high = dp.length;
        while (low < high) {
            let mid = Math.floor((low + high) / 2);
            if (dp[mid] < x) low = mid + 1;
            else high = mid;
        }
        if (low < dp.length) dp[low] = x;
        else dp.push(x);
    }
    return dp.length;
}
